use super::*;

/// Generated by upstream's `systemCredentialCipher.ts` with an injected key
/// store holding `[7; 32]`, and `createLegacyCredentialCipher` with
/// `ZCODE_CREDENTIAL_SECRET=fixture-secret-value`.
const TS_KEY: &str = "BwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwcHBwc";
const TS_OS_VALUE: &str = "enc:v2:os:4bb06f8e4e3a7715d201d573:cNwCGH7jwJceQ29E.gA9_vabTBIXENWK0-vlNsg.iKuU3yX-gSXogFOQK2Yw3w";
const TS_LEGACY_SECRET_VALUE: &str =
    "enc:v1:VM2jAgFnWpHJ9McJ.NIUDyVJ59s_sHP86tjlMWA.9XXgx0WiiqmXck8w";

#[derive(Default)]
struct MemoryKeyStore {
    value: Mutex<Option<String>>,
    sets: Mutex<usize>,
}

impl CipherKeyStore for MemoryKeyStore {
    fn get(&self) -> Result<Option<String>, String> {
        Ok(self.value.lock().unwrap().clone())
    }
    fn set(&self, encoded: &str) -> Result<(), String> {
        *self.sets.lock().unwrap() += 1;
        *self.value.lock().unwrap() = Some(encoded.to_string());
        Ok(())
    }
}

fn test_env() -> HostEnv {
    HostEnv {
        platform: "win32".into(),
        home: "C:\\Users\\test".into(),
        username: "test".into(),
        ..HostEnv::default()
    }
}

struct Fixture {
    _dir: TempDir,
    file: PathBuf,
    store: Arc<MemoryKeyStore>,
}

struct TempDir(PathBuf);
impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn fixture(key: Option<&str>) -> Fixture {
    let dir = std::env::temp_dir().join(format!("gcode-cipher-{}", uuid::Uuid::now_v7()));
    std::fs::create_dir_all(&dir).unwrap();
    let store = Arc::new(MemoryKeyStore::default());
    *store.value.lock().unwrap() = key.map(str::to_string);
    Fixture {
        file: dir.join("credentials.json"),
        _dir: TempDir(dir),
        store,
    }
}

impl Fixture {
    fn cipher(&self, env: HostEnv) -> CredentialCipher {
        CredentialCipher::new(self.file.clone(), Some(self.store.clone()), env)
    }
}

#[test]
fn decrypts_values_written_by_the_typescript_cipher() {
    let fx = fixture(Some(TS_KEY));
    std::fs::write(&fx.file, format!("{{\"a\":\"{TS_OS_VALUE}\"}}")).unwrap();
    let cipher = fx.cipher(test_env());
    assert_eq!(cipher.decrypt(TS_OS_VALUE).unwrap(), "héllo token ✓");
    let env = HostEnv {
        secret: Some("fixture-secret-value".into()),
        ..test_env()
    };
    assert_eq!(
        fx.cipher(env).decrypt(TS_LEGACY_SECRET_VALUE).unwrap(),
        "legacy value"
    );
}

#[test]
fn first_encrypt_creates_the_key_and_pins_the_os_source() {
    let fx = fixture(None);
    let cipher = fx.cipher(test_env());
    let sealed = cipher.encrypt("token").unwrap();
    assert!(sealed.starts_with("enc:v2:os:"), "{sealed}");
    assert_eq!(*fx.store.sets.lock().unwrap(), 1);
    let marker = std::fs::read_to_string(fx.file.with_file_name("credential-source")).unwrap();
    assert_eq!(marker, "os\n");
    assert_eq!(cipher.decrypt(&sealed).unwrap(), "token");
    // A fresh cipher (new process) reads the same key back.
    assert_eq!(fx.cipher(test_env()).decrypt(&sealed).unwrap(), "token");
}

#[test]
fn a_lost_key_is_never_replaced_once_the_store_depends_on_it() {
    let fx = fixture(None);
    std::fs::write(fx.file.with_file_name("credential-source"), "os\n").unwrap();
    let cipher = fx.cipher(test_env());
    assert_eq!(cipher.encrypt("x").unwrap_err().code, UNAVAILABLE);
    assert_eq!(*fx.store.sets.lock().unwrap(), 0);
    assert_eq!(cipher.decrypt(TS_OS_VALUE).unwrap_err().code, UNAVAILABLE);
}

#[test]
fn a_wrong_key_or_source_is_unavailable_not_corrupt() {
    // Corrupt would let the agent's OAuth recovery delete a still-valid login.
    let fx = fixture(Some(&B64.encode([9u8; 32])));
    let cipher = fx.cipher(test_env());
    assert_eq!(cipher.decrypt(TS_OS_VALUE).unwrap_err().code, UNAVAILABLE);
    let env_value = TS_OS_VALUE.replacen(":os:", ":env:", 1);
    assert_eq!(cipher.decrypt(&env_value).unwrap_err().code, UNAVAILABLE);
}

#[test]
fn malformed_values_fail_as_decrypt_errors() {
    let fx = fixture(Some(TS_KEY));
    let cipher = fx.cipher(test_env());
    for bad in [
        "enc:v3:whatever",
        "enc:v2:os:short:a.b.c",
        "enc:v2:os:4bb06f8e4e3a7715d201d573:a.b",
        "enc:v2:os:4bb06f8e4e3a7715d201d573:a.b.c!",
        "enc:v1:not-base64!.x.y",
    ] {
        assert_eq!(
            cipher.decrypt(bad).unwrap_err().code,
            DECRYPT_FAILED,
            "{bad}"
        );
    }
    // A changed ciphertext byte (not the discarded trailing base64 bits).
    let tampered = TS_OS_VALUE.replace(".iKuU", ".jKuU");
    assert_eq!(cipher.decrypt(&tampered).unwrap_err().code, DECRYPT_FAILED);
}

#[test]
fn plaintext_passes_through_and_legacy_default_key_round_trips() {
    let fx = fixture(Some(TS_KEY));
    let cipher = fx.cipher(test_env());
    assert_eq!(cipher.decrypt("plain-value").unwrap(), "plain-value");
    let seed = "zcode-credential-fallback:win32:C:\\Users\\test:test";
    let legacy = format!(
        "{LEGACY_PREFIX}{}",
        seal("old", &sha256(seed.as_bytes())).unwrap()
    );
    assert_eq!(cipher.decrypt(&legacy).unwrap(), "old");
}

#[test]
fn managed_secret_takes_over_and_both_sources_conflict() {
    let fx = fixture(None);
    let env = HostEnv {
        secret: Some("s".repeat(40)),
        ..test_env()
    };
    let sealed = fx.cipher(env.clone()).encrypt("v").unwrap();
    assert!(sealed.starts_with("enc:v2:env:"));
    assert_eq!(fx.cipher(env).decrypt(&sealed).unwrap(), "v");
    assert_eq!(
        *fx.store.sets.lock().unwrap(),
        0,
        "the OS store is not touched"
    );
    let both = HostEnv {
        secret: Some("s".repeat(40)),
        secret_file: Some("x".into()),
        ..test_env()
    };
    assert_eq!(fx.cipher(both).encrypt("v").unwrap_err().code, UNAVAILABLE);
}

#[test]
fn account_is_the_sha256_of_the_path() {
    assert_eq!(
        account_for(Path::new("abc")),
        "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
    );
}

/// Manual check against this machine's real credentials file and OS entry
/// (`cargo test -- --ignored real_store_decrypts`): prints only counts, never
/// values. Decrypt-only, so it never creates a key or the source marker.
#[cfg(not(target_os = "android"))]
#[test]
#[ignore]
fn real_store_decrypts() {
    let file = crate::shared::settings::settings_file_path().with_file_name("credentials.json");
    let cipher = CredentialCipher::new(file.clone(), os_key_store(&file), HostEnv::from_process());
    let raw: serde_json::Map<String, serde_json::Value> =
        serde_json::from_str(&std::fs::read_to_string(&file).unwrap()).unwrap();
    let (mut ok, mut failed) = (0, Vec::new());
    for value in raw.values().filter_map(|v| v.as_str()) {
        match cipher.decrypt(value) {
            Ok(_) => ok += 1,
            Err(e) => failed.push((value.get(..10).unwrap_or(value).to_string(), e.code)),
        }
    }
    println!("decrypted {ok}, failed {failed:?}");
    assert!(failed.is_empty());
}
